from sage.all_cmdline import *   # import sage library

_sage_const_300 = Integer(300); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_10 = Integer(10); _sage_const_6 = Integer(6); _sage_const_3 = Integer(3); _sage_const_100 = Integer(100); _sage_const_0p4407 = RealNumber('0.4407'); _sage_const_0p2 = RealNumber('0.2'); _sage_const_0p813 = RealNumber('0.813'); _sage_const_0p05 = RealNumber('0.05'); _sage_const_0p1 = RealNumber('0.1'); _sage_const_0p4 = RealNumber('0.4'); _sage_const_0p8 = RealNumber('0.8'); _sage_const_1p2 = RealNumber('1.2'); _sage_const_0p3 = RealNumber('0.3'); _sage_const_1p7 = RealNumber('1.7'); _sage_const_5p0 = RealNumber('5.0'); _sage_const_10p4 = RealNumber('10.4'); _sage_const_25 = Integer(25); _sage_const_0 = Integer(0)# ---------------------------------------------------------
# <cosh_sinh_basic_properties> (3)  x > 0 ならば cosh x > sinh x > 0
#
# 反例探索の方針: 主張は x>0 でのみ成り立つ。x<=0 では sinh x <= 0 になり
# 「sinh x > 0」が破れるはずなので、x<=0 でも走査して
#   「x>0 のとき成立し、x<=0 のとき sinh x <= 0 である」
# の両方を確認する。x>0 側だけを見て通すと、主張の仮定 x>0 が効いていることを
# 検証したことにならない。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_300 )

def sinh_def(x):
    return (RF(x).exp() - RF(-x).exp()) / _sage_const_2 

def cosh_def(x):
    return (RF(x).exp() + RF(-x).exp()) / _sage_const_2 

POS = [RF(v) for v in [
    _sage_const_1 /_sage_const_10 **_sage_const_6 , _sage_const_1 /_sage_const_10 **_sage_const_3 , _sage_const_1 /_sage_const_100 , _sage_const_1 /_sage_const_10 , _sage_const_1 /_sage_const_2 , _sage_const_1 , _sage_const_2 ,
    _sage_const_2 *_sage_const_0p4407 , _sage_const_2 *_sage_const_0p2 , _sage_const_2 *_sage_const_0p813 , _sage_const_2 *_sage_const_0p05 , _sage_const_2 *_sage_const_0p1 ,
    _sage_const_2 *_sage_const_0p4 , _sage_const_2 *_sage_const_0p8 , _sage_const_2 *_sage_const_1p2 , _sage_const_2 *_sage_const_0p3 , _sage_const_2 *_sage_const_1p7 , _sage_const_2 *_sage_const_5p0 , _sage_const_2 *_sage_const_10p4 , _sage_const_25 ,
]]
NONPOS = [RF(_sage_const_0 )] + [-v for v in POS]

rep = CheckReport("<cosh_sinh_basic_properties> (3) x>0 => cosh x > sinh x > 0")

for x in POS:
    c, s = cosh_def(x), sinh_def(x)
    rep.truth(s > _sage_const_0 , "sinh>0 @x=%s" % x)
    rep.truth(c > s, "cosh>sinh @x=%s" % x)

for x in NONPOS:
    s = sinh_def(x)
    rep.truth(s <= _sage_const_0 , "x<=0 では sinh<=0（仮定 x>0 が効いていること）@x=%s" % x)
    # cosh > sinh は x の符号によらず成り立つ（(1) より）
    rep.truth(cosh_def(x) > s, "cosh>sinh は x<=0 でも成立 @x=%s" % x)

rep.finish()

